export const messages = {
  'checkout.address.title': {
    de: 'Adresse',
    fr: 'Adresse',
    it: 'Indirizzo',
  },
  'checkout.address.label.DEFAULT': {
    de: 'Lieferadresse',
    fr: 'Adresse de livraison',
    it: 'Indirizzo di consegna',
  },
  'checkout.address.label.INVOICE': {
    de: 'Rechnungsadresse',
    it: 'Indirizzo di fatturazione',
    fr: 'Adresse de facturation',
  },
  'checkout.address.hint': {
    de: 'Strasse und Hausnummer',
    fr: 'Rue et numéro',
    it: 'Via e numero civico',
  },
};

export type AddressType = 'DEFAULT' | 'INVOICE';

export function addressLabel(type: AddressType, lang: 'de' | 'fr' | 'it'): string {
  return messages[`checkout.address.label.${type}`][lang];
}
